  getSpeakerClass(line: number): string {
    if (line % 5 === 0) return 'line-SPKR';
    if (line % 5 === 1) return 'line-SPKR-CONTINUE';
    if (line % 5 === 2) return 'line-ANS-CONTINUE';
    if (line % 5 === 3) return 'line-RHT-FLS';
    return 'line-PRNTH';
  }

