  // Helper method to extract all CSS variables from computed style
  private extractCssVariables(computedStyle: CSSStyleDeclaration): Record<string, string> {
    const cssVariables: Record<string, string> = {};
    for (let i = 0; i < computedStyle.length; i++) {
      const prop = computedStyle[i];
      if (prop.startsWith('--')) {
        // Store the variable name without -- prefix
        const key = prop.substring(2);
        const value = computedStyle.getPropertyValue(prop).trim();
        if (value) {
          cssVariables[key] = value;
        }
      }
    }
    return cssVariables;
  }

  // Helper method to generate CSS variables string for injection
  private generateCssVariablesString(cssVariables: Record<string, string>): string {
    return Object.entries(cssVariables)
      .map(([key, value]) => `--${key}: ${value};`)
      .join('\n              ');
  }




  deteectlinebreak(linetext: string): boolean {
    const computedStyle = getComputedStyle(document.body);
    // Create a canvas for text measurement
    const canvas = document.createElement('canvas');
    const ctx = canvas.getContext('2d')!;

    // Set font for measurement based on computed style
    const fontFamily = computedStyle.getPropertyValue('--body-font-family') || 'Arial, sans-serif';
    const fontSize = computedStyle.getPropertyValue('--body-font-size') || '16px';
    const letterSpacing = computedStyle.getPropertyValue('--body-letter-spacing') || '0px';
    const fontWeight = 'normal';
    ctx.font = `${fontWeight} ${fontSize} ${fontFamily}`;

    // Get effective width (container width minus padding)
    const effectiveWidth = 548; // 10px padding on each side

    // Measure text width
    let textWidth = ctx.measureText(linetext).width;

    if (letterSpacing !== '0px') {
      // Convert letter spacing to pixels
      let letterSpacingPx = parseFloat(letterSpacing);

      // Add extra width for letter spacing (character count - 1) * letter spacing
      if (letterSpacingPx !== 0) {
        const charCount = linetext.length;
        textWidth += (charCount - 1) * letterSpacingPx;
      }
    }

    // Return true if the text would need to break
    return textWidth > effectiveWidth;

  }


