  // Check if a specific checkbox is checked
  isChecked(name: string): boolean {
    return this.checkboxStates[name as keyof typeof this.checkboxStates];
  }

  // Toggle checkbox state
  toggleCheckbox(checkboxName: string): void {
    const key = checkboxName as keyof typeof this.checkboxStates;
    this.checkboxStates[key] = !this.checkboxStates[key];
  }

